mapper.select:
select 
from preg_expense e
where e.del_flag = '0'

    and e.spent_date >= #{from}


    and e.spent_date <= #{to}


    and e.category_code = #{category}


    and e.source_type = #{sourceType}

order by e.spent_date desc, e.id desc

select e.spent_date as spentDate, sum(e.amount) as total
from preg_expense e
where e.spent_date >= #{from}
  and e.spent_date <= #{to}
  and e.del_flag = '0'
group by e.spent_date

select e.category_code as categoryCode, e.source_type as sourceType, sum(e.amount) as total from preg_expense e where e.del_flag = '0'
and e.spent_date >= #{from}
and e.spent_date <= #{to}
group by e.category_code, e.source_type order by e.category_code asc, e.source_type asc

select sum(e.amount)
from preg_expense e
where e.del_flag = '0'

    and e.spent_date >= #{from}


    and e.spent_date <= #{to}
